public class AttributeFilterGameTests {
    @GameTest public void actualCreateTabRetainsAllScaffoldBindingsAndFreshDisplayStacksAcrossNativeRebuilds(GameTestHelper h){
        var scaffolds=List.of(AllBlocks.ANDESITE_SCAFFOLD,AllBlocks.BRASS_SCAFFOLD,AllBlocks.COPPER_SCAFFOLD);
        for(var scaffold:scaffolds){
            var expected=BuiltInRegistries.ITEM.getValue(BuiltInRegistries.BLOCK.getKey(scaffold));
            h.assertTrue(expected!=Items.AIR&&expected instanceof com.simibubi.create.content.decoration.MetalScaffoldingBlockItem item&&item.getBlock()==scaffold,"Native item registry retains each genuine metal scaffold block item");
            h.assertTrue(Item.byBlock(scaffold)==expected&&scaffold.asItem()==expected,"Early Fabric shape baking cannot cache AIR ahead of the real item association");
            var actual=new ItemStack(scaffold);h.assertTrue(actual.is(expected)&&actual.getCount()==1,"Ordinary native block-to-stack construction yields the registered scaffold and one item");
        }
        var tab=BuiltInRegistries.CREATIVE_MODE_TAB.getValue(Create.asResource("base"));h.assertTrue(tab!=null,"Actual registered Create creative category exists");
        var parameters=new CreativeModeTab.ItemDisplayParameters(h.getLevel().enabledFeatures(),false,h.getLevel().registryAccess());var previous=new ArrayList<ItemStack>();
        try{
            for(int rebuild=0;rebuild<3;rebuild++){
                tab.buildContents(parameters);h.assertTrue(!tab.getDisplayItems().isEmpty()&&tab.getDisplayItems().stream().allMatch(stack->!stack.isEmpty()&&stack.getCount()==1),"Native Create tab builder accepts every actual display entry without normalization or skipped items");
                for(int index=0;index<scaffolds.size();index++){
                    var expected=Item.byBlock(scaffolds.get(index));var matches=tab.getDisplayItems().stream().filter(stack->stack.is(expected)).toList();h.assertValueEqual(matches.size(),1,"Every metal scaffold appears once in the real Create display");var display=matches.getFirst();
                    h.assertTrue(!display.has(DataComponents.CUSTOM_NAME)&&display.getCount()==1,"Each rebuild produces a fresh unmodified scaffold display value");
                    if(rebuild>0){var old=previous.get(index);h.assertTrue(display!=old&&old.getCount()==7&&old.has(DataComponents.CUSTOM_NAME),"Rebuild allocates a new display owner and leaves the previous returned stack untouched");}
                    h.assertTrue(new InItemGroupAttribute(tab).appliesTo(new ItemStack(expected,32),h.getLevel()),"Actual server attribute discovery retains Create group membership for a real scaffold stack");
                    if(rebuild==0)previous.add(display);else previous.set(index,display);
                }
                for(var display:previous){display.setCount(7);display.set(DataComponents.CUSTOM_NAME,net.minecraft.network.chat.Component.literal("Previous creative display owner"));}
            }
        }finally{tab.buildContents(parameters);}
        h.assertTrue(tab.getDisplayItems().stream().allMatch(stack->!stack.isEmpty()&&stack.getCount()==1&&!stack.has(DataComponents.CUSTOM_NAME)),"Final actual tab rebuild restores clean native display ownership");h.succeed();
    }
    @GameTest public void emptyFluidContainerRetainsSourceEmptyContentsAttribute(GameTestHelper h){
        var bucket=new ItemStack(Items.BUCKET);h.assertTrue(new FluidContentsAttribute(net.minecraft.world.level.material.Fluids.EMPTY).appliesTo(bucket,h.getLevel()),"Empty tank contributes its empty-fluid identity as in source");h.assertFalse(new FluidContentsAttribute(net.minecraft.world.level.material.Fluids.EMPTY).appliesTo(new ItemStack(Items.DIAMOND),h.getLevel()),"Non-container has no tank to match");h.succeed();
    }
    @GameTest public void arbitraryFireworkRGBNeverCreatesNullDyeAttribute(GameTestHelper h){
        var star=new ItemStack(Items.FIREWORK_STAR);star.set(DataComponents.FIREWORK_EXPLOSION,new FireworkExplosion(FireworkExplosion.Shape.STAR,it.unimi.dsi.fastutil.ints.IntList.of(DyeColor.BLUE.getFireworkColor(),0x123456),it.unimi.dsi.fastutil.ints.IntList.of(DyeColor.RED.getFireworkColor()),false,false));var attributes=AllItemAttributeTypes.HAS_COLOR.getAllAttributes(star,h.getLevel());h.assertValueEqual(attributes.size(),2,"Only matching named dye colors enumerated");for(var attribute:attributes)h.assertTrue(ItemAttribute.loadStatic(ItemAttribute.saveStatic(attribute,h.getLevel().registryAccess()),h.getLevel().registryAccess())!=null,"Firework color persists");h.succeed();
    }
    @GameTest public void menuRejectsSelectionFromEarlierReferenceRevision(GameTestHelper h){
        var player=h.makeMockPlayer(GameType.SURVIVAL);var item=new ItemStack(AllItems.ATTRIBUTE_FILTER);player.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,item);player.getInventory().setItem(9,new ItemStack(Items.APPLE));var menu=new AttributeFilterMenu(1,player.getInventory(),item,player.getInventory().getSelectedSlot());menu.quickMoveStack(player,0);int previous=menu.revision();player.getInventory().setItem(9,new ItemStack(Items.DIAMOND));menu.quickMoveStack(player,0);h.assertFalse(menu.addAttribute(player,0,false,previous),"Delayed old-reference packet rejected");h.assertTrue(menu.selected().isEmpty(),"Stale packet cannot select a different new-reference property");h.succeed();
    }
    @GameTest public void addonRegistersItsOwnAttributeAndPersistsInConfiguredFilter(GameTestHelper h){
        var attribute=RuntimeWoodFixtures.ADDON_ATTRIBUTE.createAttribute();h.assertTrue(ItemAttribute.getAllAttributes(new ItemStack(RuntimeWoodFixtures.ASSEMBLY_BLANK),h.getLevel()).contains(attribute),"Addon type participates in discovery");var original=filter(AttributeFilterWhitelistMode.WHITELIST_DISJ,new ItemAttributeEntry(attribute,false));var ops=h.getLevel().registryAccess().createSerializationContext(net.minecraft.nbt.NbtOps.INSTANCE);var restored=ItemStack.CODEC.parse(ops,ItemStack.CODEC.encodeStart(ops,original).getOrThrow()).getOrThrow();h.assertTrue(FilterItemStack.of(restored).test(h.getLevel(),new ItemStack(RuntimeWoodFixtures.ASSEMBLY_BLANK)),"Addon filter persisted");h.assertFalse(FilterItemStack.of(restored).test(h.getLevel(),new ItemStack(Items.DIAMOND)),"Addon predicate enforced");h.succeed();
    }
    private static void matches(GameTestHelper h,ItemAttributeType type,Item yes,Item no){h.assertTrue(type.createAttribute().appliesTo(new ItemStack(yes),h.getLevel()),"Positive "+type.createAttribute().getTranslationKey());h.assertFalse(type.createAttribute().appliesTo(new ItemStack(no),h.getLevel()),"Negative "+type.createAttribute().getTranslationKey());}
    public static ItemStack filter(AttributeFilterWhitelistMode mode,ItemAttributeEntry... entries){var filter=new ItemStack(AllItems.ATTRIBUTE_FILTER);filter.set(AllDataComponents.ATTRIBUTE_FILTER_WHITELIST_MODE,mode);filter.set(AllDataComponents.ATTRIBUTE_FILTER_MATCHED_ATTRIBUTES,List.of(entries));return filter;}
    @GameTest public void allOriginalTypesRegisterAndSimplePropertiesUseModernComponents(GameTestHelper h){
        h.assertValueEqual(CreateBuiltInRegistries.ITEM_ATTRIBUTE_TYPE.stream().filter(type->CreateBuiltInRegistries.ITEM_ATTRIBUTE_TYPE.getKey(type).getNamespace().equals("create")).count(),28L,"Every original attribute type registered");matches(h,AllItemAttributeTypes.PLACEABLE,Items.STONE,Items.DIAMOND);matches(h,AllItemAttributeTypes.CONSUMABLE,Items.APPLE,Items.DIAMOND);matches(h,AllItemAttributeTypes.FLUID_CONTAINER,Items.BUCKET,Items.DIAMOND);matches(h,AllItemAttributeTypes.NOT_STACKABLE,Items.DIAMOND_PICKAXE,Items.APPLE);matches(h,AllItemAttributeTypes.EQUIPABLE,Items.DIAMOND_HELMET,Items.DIAMOND_SWORD);matches(h,AllItemAttributeTypes.FURNACE_FUEL,Items.COAL,Items.DIAMOND);matches(h,AllItemAttributeTypes.COMPOSTABLE,Items.WHEAT_SEEDS,Items.DIAMOND);h.succeed();
    }
    @GameTest public void recipeAttributesUseServerRecipesIncludingRuntimeCreateRecipes(GameTestHelper h){
        matches(h,AllItemAttributeTypes.WASHABLE,AllItems.CRUSHED_IRON,Items.DIAMOND);matches(h,AllItemAttributeTypes.HAUNTABLE,Items.SAND,Items.DIAMOND);matches(h,AllItemAttributeTypes.CRUSHABLE,Items.WHEAT,Items.DIAMOND);matches(h,AllItemAttributeTypes.SMELTABLE,Items.RAW_IRON,Items.DIAMOND);matches(h,AllItemAttributeTypes.SMOKABLE,Items.BEEF,Items.DIAMOND);matches(h,AllItemAttributeTypes.BLASTABLE,Items.RAW_GOLD,Items.DIAMOND);h.succeed();
    }
    @GameTest public void nameDamageAndSpecificEnchantmentAttributesDistinguishComponents(GameTestHelper h){
        var tool=new ItemStack(Items.DIAMOND_PICKAXE);tool.setDamageValue(tool.getMaxDamage()*3/4);h.assertTrue(AllItemAttributeTypes.DAMAGED.createAttribute().appliesTo(tool,h.getLevel()),"Damaged tool detected");h.assertFalse(AllItemAttributeTypes.BADLY_DAMAGED.createAttribute().appliesTo(tool,h.getLevel()),"75 percent boundary is strict");tool.setDamageValue(tool.getMaxDamage()*3/4+2);h.assertTrue(AllItemAttributeTypes.BADLY_DAMAGED.createAttribute().appliesTo(tool,h.getLevel()),"Beyond 75 percent detected");tool.set(DataComponents.CUSTOM_NAME,net.minecraft.network.chat.Component.literal("Mining rig"));h.assertTrue(new ItemNameAttribute("Mining rig").appliesTo(tool,h.getLevel()),"Native component name read without obsolete JSON parsing");h.assertTrue(AllItemAttributeTypes.RENAMED.createAttribute().appliesTo(tool,h.getLevel()),"Renamed trait");var enchant=h.getLevel().registryAccess().lookupOrThrow(Registries.ENCHANTMENT).getOrThrow(Enchantments.UNBREAKING);tool.enchant(enchant,3);h.assertTrue(AllItemAttributeTypes.ENCHANTED.createAttribute().appliesTo(tool,h.getLevel()),"Enchanted trait");h.assertTrue(AllItemAttributeTypes.MAX_ENCHANTED.createAttribute().appliesTo(tool,h.getLevel()),"Max enchantment trait");h.assertTrue(new EnchantAttribute(enchant).appliesTo(tool,h.getLevel()),"Specific enchantment");h.succeed();
    }
    @GameTest public void tagsModsGroupsColorsAndFluidContentsDiscoverAllParameterValues(GameTestHelper h){
        var log=new ItemStack(Items.OAK_LOG);h.assertTrue(new InTagAttribute(net.minecraft.tags.ItemTags.LOGS).appliesTo(log,h.getLevel()),"Tag attribute");h.assertTrue(new AddedByAttribute("create").appliesTo(new ItemStack(AllItems.ANDESITE_ALLOY),h.getLevel()),"Fabric mod namespace");h.assertTrue(new ColorAttribute(DyeColor.RED).appliesTo(new ItemStack(Items.WOOL.pick(DyeColor.RED)),h.getLevel()),"Block color");h.assertTrue(new ColorAttribute(DyeColor.BLUE).appliesTo(new ItemStack(Items.DYE.pick(DyeColor.BLUE)),h.getLevel()),"Dye component");h.assertTrue(new FluidContentsAttribute(net.minecraft.world.level.material.Fluids.WATER).appliesTo(new ItemStack(Items.WATER_BUCKET),h.getLevel()),"Fabric fluid container");h.assertFalse(new FluidContentsAttribute(net.minecraft.world.level.material.Fluids.WATER).appliesTo(new ItemStack(Items.LAVA_BUCKET),h.getLevel()),"Different fluid rejected");var attributes=ItemAttribute.getAllAttributes(log,h.getLevel());h.assertTrue(attributes.stream().anyMatch(a->a instanceof InItemGroupAttribute),"Creative tabs built for server discovery");h.assertTrue(attributes.stream().anyMatch(a->a instanceof InTagAttribute tag&&tag.tag().equals(net.minecraft.tags.ItemTags.LOGS)),"All tag parameters discovered");h.succeed();
    }
    @GameTest public void shulkerContentsAndBookMetadataHaveSourceRules(GameTestHelper h){
        var shulker=new ItemStack(Items.SHULKER_BOX);h.assertTrue(new ShulkerFillLevelAttribute(ShulkerFillLevelAttribute.ShulkerLevels.EMPTY).appliesTo(shulker,h.getLevel()),"Empty shulker");shulker.set(DataComponents.CONTAINER,ItemContainerContents.fromItems(List.of(new ItemStack(Items.APPLE))));h.assertTrue(new ShulkerFillLevelAttribute(ShulkerFillLevelAttribute.ShulkerLevels.PARTIAL).appliesTo(shulker,h.getLevel()),"Partial shulker");var full=new ArrayList<ItemStack>();for(int i=0;i<27;i++)full.add(new ItemStack(Items.APPLE,64));shulker.set(DataComponents.CONTAINER,ItemContainerContents.fromItems(full));h.assertTrue(new ShulkerFillLevelAttribute(ShulkerFillLevelAttribute.ShulkerLevels.FULL).appliesTo(shulker,h.getLevel()),"All 27 full stacks");var book=new ItemStack(Items.WRITTEN_BOOK);book.set(DataComponents.WRITTEN_BOOK_CONTENT,new WrittenBookContent(net.minecraft.server.network.Filterable.passThrough("Factory"),"Engineer",2,List.of(),true));h.assertTrue(new BookAuthorAttribute("Engineer").appliesTo(book,h.getLevel()),"Book author");h.assertTrue(new BookCopyAttribute(2).appliesTo(book,h.getLevel()),"Book copy generation");h.succeed();
    }
    @GameTest public void allAnyDenyAndInversionApplyInsideNestedRegularFilters(GameTestHelper h){
        var block=new ItemAttributeEntry(AllItemAttributeTypes.PLACEABLE.createAttribute(),false);var edible=new ItemAttributeEntry(AllItemAttributeTypes.CONSUMABLE.createAttribute(),false);var any=filter(AttributeFilterWhitelistMode.WHITELIST_DISJ,block,edible);h.assertTrue(FilterItemStack.of(any).test(h.getLevel(),new ItemStack(Items.APPLE)),"Any accepts food");h.assertFalse(FilterItemStack.of(any).test(h.getLevel(),new ItemStack(Items.DIAMOND)),"Any rejects unrelated");var all=filter(AttributeFilterWhitelistMode.WHITELIST_CONJ,block,new ItemAttributeEntry(AllItemAttributeTypes.CONSUMABLE.createAttribute(),true));h.assertTrue(FilterItemStack.of(all).test(h.getLevel(),new ItemStack(Items.STONE)),"All handles inverted trait");h.assertFalse(FilterItemStack.of(all).test(h.getLevel(),new ItemStack(Items.APPLE)),"All requires placeable");var deny=filter(AttributeFilterWhitelistMode.BLACKLIST,edible);h.assertFalse(FilterItemStack.of(deny).test(h.getLevel(),new ItemStack(Items.APPLE)),"Deny rejects matched food");h.assertTrue(FilterItemStack.of(deny).test(h.getLevel(),new ItemStack(Items.DIAMOND)),"Deny passes non-food");h.assertTrue(FilterItemStack.of(FilterGameTests.filter(false,false,any)).test(h.getLevel(),new ItemStack(Items.APPLE)),"Attribute filter nests in regular list");h.assertFalse(FilterItemStack.of(any).test(h.getLevel(),new com.simibubi.create.foundation.fluid.FluidStack(net.fabricmc.fabric.api.transfer.v1.fluid.FluidVariant.of(net.minecraft.world.level.material.Fluids.WATER),81000)),"Attribute filters do not filter bare fluid stacks");h.succeed();
    }
    @GameTest public void discoveredAttributesRoundTripThroughSourceNBTAndModernNetworkCodecs(GameTestHelper h){
        var sample=new ItemStack(Items.DYED_SHULKER_BOX.pick(DyeColor.RED));sample.set(DataComponents.CUSTOM_NAME,net.minecraft.network.chat.Component.literal("Copper crates"));var discovered=ItemAttribute.getAllAttributes(sample,h.getLevel());for(var attribute:discovered){var saved=ItemAttribute.saveStatic(attribute,h.getLevel().registryAccess());var loaded=ItemAttribute.loadStatic(saved,h.getLevel().registryAccess());h.assertTrue(loaded!=null,"Attribute restored from original envelope");h.assertValueEqual(ItemAttribute.saveStatic(loaded,h.getLevel().registryAccess()),saved,"Attribute data round trip");var buffer=new RegistryFriendlyByteBuf(io.netty.buffer.Unpooled.buffer(),h.getLevel().registryAccess());try{ItemAttribute.STREAM_CODEC.encode(buffer,attribute);var decoded=ItemAttribute.STREAM_CODEC.decode(buffer);h.assertValueEqual(ItemAttribute.saveStatic(decoded,h.getLevel().registryAccess()),saved,"Custom registry network round trip");}finally{buffer.release();}}var item=filter(AttributeFilterWhitelistMode.BLACKLIST,new ItemAttributeEntry(new AddedByAttribute("minecraft"),true));var ops=h.getLevel().registryAccess().createSerializationContext(net.minecraft.nbt.NbtOps.INSTANCE);var restored=ItemStack.CODEC.parse(ops,ItemStack.CODEC.encodeStart(ops,item).getOrThrow()).getOrThrow();h.assertTrue(ItemStack.isSameItemSameComponents(item,restored),"Attribute item components persist");h.succeed();
    }
    @GameTest public void menuDiscoversOnServerAcceptsOnlyCurrentChoicesAndNeverConsumesReference(GameTestHelper h){
        var player=h.makeMockPlayer(GameType.SURVIVAL);var item=new ItemStack(AllItems.ATTRIBUTE_FILTER);player.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,item);player.getInventory().setItem(9,new ItemStack(Items.APPLE,16));var menu=new AttributeFilterMenu(1,player.getInventory(),item,player.getInventory().getSelectedSlot());menu.quickMoveStack(player,0);h.assertValueEqual(player.getInventory().getItem(9).getCount(),16,"Reference is a ghost");int food=-1;for(int i=0;i<menu.available().size();i++)if(menu.available().get(i).getType()==AllItemAttributeTypes.CONSUMABLE)food=i;h.assertTrue(food>=0,"Server discovery includes consumable");h.assertFalse(menu.addAttribute(player,-1,false),"Invalid attribute index rejected");h.assertTrue(menu.addAttribute(player,food,true),"Inverted choice accepted");h.assertFalse(menu.addAttribute(player,food,false),"Same attribute cannot be added twice");menu.clickMenuButton(player,1);h.assertValueEqual(menu.mode(),AttributeFilterWhitelistMode.WHITELIST_CONJ,"All mode saved");menu.clicked(37,0,ContainerInput.PICKUP,player);h.assertTrue(menu.getCarried().isEmpty(),"Summary ghost cannot become real item");menu.quickMoveStack(player,36);h.assertTrue(menu.available().isEmpty(),"Clearing reference clears available choices");h.assertFalse(menu.addAttribute(player,food,false),"Stale choice rejected");menu.removed(player);h.assertValueEqual(item.get(AllDataComponents.ATTRIBUTE_FILTER_MATCHED_ATTRIBUTES).size(),1,"Selected condition saved after reference cleared");h.succeed();
    }
}
